'use strict';
// Configure the exact group URL only after JV supplies it. Never guess a group identity.
const FACEBOOK_COMMUNITY_URL='';
state.theme=state.theme==='dark'?'dark':'light';state.profile.email=state.profile.email||'';state.hubOnboardingCompleted=!!state.hubOnboardingCompleted;state.feedback=state.feedback||[];
const mainRenderBeforeFlow=render,mainNavBeforeFlow=nav,profileBeforeFlow=profile;
let pendingProfileDraft=null;
function applyTheme(){document.documentElement.setAttribute('data-theme',state.theme)}
function welcomeView(){app.innerHTML=`<section class="card short-welcome"><span class="welcome-step">1 OF 3 · WELCOME ABOARD</span><img src="assets/seafarer-mascot.webp" alt="JV’s seafarer mascot welcoming you aboard"><h1>Hi, I’m JV.<br>A seafarer, just like you.</h1><p>Useful answers get buried in busy group chats. I wanted a better way to keep them within reach.</p><p>That’s why I built <strong>Toolbox</strong>: a place to ask questions, share experience, and find useful answers again.</p><p><strong>What you know today could help the next crew.</strong></p><div class="short-signature">— JV Ursal</div><button class="btn" data-nav="gettingstarted">Let’s get started →</button><p class="hint short-welcome-storage">${globalThis.HubRuntime?.enabled?'Your email stays private.':'Preview: data is saved in this browser.'} <button class="text-button" data-nav="privacy">Privacy</button></p></section>`}
function gettingStartedView(){app.innerHTML=`<section class="card getting-started"><button class="back" data-nav="welcome">← Welcome</button><span class="welcome-step">2 OF 3 · GETTING STARTED</span><h1>Find your way, crew.</h1><div class="getting-started-steps">${[['＋','Ask','Have a question? Choose Ask. Add context and a photo when safe and permitted.'],['↗','Answer','Have experience to share? Choose Answer, then select topics you can help with.'],['▤','Library','Choose a topic first. Find a useful discussion and save it for later.'],['✓','Review','Optional OIC NW / EW practice. Try short rounds, see your scores, and revisit mistakes.']].map(([symbol,title,copy])=>`<div class="getting-started-row"><span aria-hidden="true">${symbol}</span><div><strong>${title}</strong><p>${copy}</p></div></div>`).join('')}</div><p class="getting-started-footer"><strong>Progress</strong> shows your contributions and badges. <strong>Profile</strong> holds your details and settings. On your phone, use the bottom tabs to navigate.</p><button class="btn" id="beginProfile">Set up my profile →</button><p class="hint">Next: your name, rank, department, and email. Photo and bio are optional.</p></section>`;document.querySelector('#beginProfile').onclick=()=>{state.hubTourCompleted=true;persist();nav('setup')}}

function profileLinks(){return `<section class="card profile-settings"><h3 style="font-size:16px;margin-top:0">Settings</h3><p class="hint">Choose the appearance that feels comfortable.</p><div class="theme-options"><button data-theme-choice="light" class="${state.theme==='light'?'active':''}" aria-pressed="${state.theme==='light'}">☀ Light</button><button data-theme-choice="dark" class="${state.theme==='dark'?'active':''}" aria-pressed="${state.theme==='dark'}">☾ Dark</button></div><div class="profile-links"><button class="profile-action" data-nav="welcome"><span>JV’s welcome message</span><small>Read again →</small></button><button class="profile-action" data-nav="privacy"><span>Privacy policy</span><small>Your information →</small></button><button class="profile-action" data-nav="feedback"><span>Feedback</span><small>Help improve the app →</small></button><button class="profile-action" data-nav="community"><span>Facebook community</span><small>Connect outside the app →</small></button></div></section>`}
profile=function(setup=false){const storedProfile=state.profile;if(pendingProfileDraft)state.profile={...storedProfile,...pendingProfileDraft};profileBeforeFlow();state.profile=storedProfile;const rankLine=document.querySelector('.qa-profile-title p');if(rankLine){rankLine.className='profile-rank';rankLine.textContent=state.profile.rank?.trim()||'Add your rank / role'}const form=document.querySelector('#qaProfileForm');form.oninput=()=>{pendingProfileDraft=Object.fromEntries(new FormData(form))};form.insertAdjacentHTML('afterbegin',`<label class="field">Email ${setup?'':'(local preview)'}<input type="email" name="email" required maxlength="254" autocomplete="email" value="${esc(pendingProfileDraft?.email??state.profile.email)}" placeholder="you@example.com"></label><p class="profile-email-note">Email is kept in your local profile. Sign-in is available when cloud access is connected.</p>`);form.querySelector('input[name="rank"]').required=true;form.querySelector('select[name="department"]').required=true;form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.name?.trim()||!data.rank?.trim()||!data.department||(globalThis.HubRuntime?.enabled&&!data.email?.trim())){toast('Complete your name, rank, department, and email.');return}const previous={profile:{...state.profile},complete:state.hubOnboardingCompleted};state.profile={...state.profile,...data,name:data.name.trim(),rank:data.rank.trim(),email:(data.email||'').trim()};if(setup)state.hubOnboardingCompleted=true;if(!persist()){state.profile=previous.profile;state.hubOnboardingCompleted=previous.complete;return}pendingProfileDraft=null;if(setup){page='home';render();window.scrollTo(0,0);toast('Welcome aboard. Your profile is ready in this browser.')}else{render();toast('Profile saved in this browser.')}};if(setup){app.classList.add('setup-view');app.insertAdjacentHTML('afterbegin','<div class="setup-head"><button class="back" data-nav="gettingstarted">← Getting started</button><div class="eyebrow" style="font-size:10px;color:var(--teal)">3 OF 3 · YOUR SEAFARER PROFILE</div><h1>Make Toolbox yours.</h1><p>Add your name, rank, department, and email. A photo and bio are optional.</p></div>');form.querySelector('button[type="submit"],button.btn').textContent='Finish setup & open dashboard →'}else{const aside=document.querySelector('.profile-grid>div');if(aside)aside.insertAdjacentHTML('beforeend',profileLinks())}};
function privacyView(){app.innerHTML=`<button class="back" data-nav="${state.hubOnboardingCompleted?'profile':'welcome'}">← ${state.hubOnboardingCompleted?'Profile':'Welcome'}</button><article class="card privacy-copy"><div class="eyebrow" style="font-size:10px;color:var(--teal)">PRIVACY POLICY · PROTOTYPE NOTICE</div><h1 class="page-title" style="margin-top:14px">Your information, explained.</h1><p>This notice covers the current browser-local Toolbox prototype, created by JV Ursal. It does not describe a live account or cloud service. You will need an updated notice before shared accounts launch.</p><h2>What you enter</h2><p>Your local profile can include your name, rank, department, email, optional photo, country, experience, and bio. The prototype also stores test questions, answers, attached photos, reported outcomes, saved questions, favorite topics, topic visits, participation milestones, local reports, feedback drafts, appearance preferences, and optional reviewer selections, quiz answers, practice results, progress, and local question flags.</p><h2>Where it is stored and why</h2><p>App-entered records are stored in this browser to let you test the experience, return to entries, and personalize the dashboard. Text drafts may also be kept in this browser tab. There is no automatic synchronization or live account verification.</p><p>The app code does not send these entered records to a shared database. People with access to the same browser profile may be able to read them. This storage is not a secure vault; avoid confidential vessel, company, or personal documents.</p><h2>Profile details and email</h2><p>Email stays in the local profile and is not added to question cards or prepared feedback. Rank and experience are self-reported. In a future shared version, the app must clearly identify public profile fields and private account information before publishing them.</p><h2>Photos</h2><p>Photos you choose are resized by the browser and stored with local test entries or your profile. Upload only what you are permitted to share. A live service will need additional upload and storage protections.</p><h2>Feedback and Facebook</h2><p>Feedback is saved locally and prepared as text for you to copy. It is not automatically delivered to JV. If you choose to paste it into another service, that service’s policies apply. A configured Facebook community link opens Facebook separately; your local profile is not automatically transferred to it.</p><h2>Your control and retention</h2><p>Edit your profile, remove its photo, and change favorite topics in Profile. Local records remain until you or your browser remove the site’s data. Clearing browser/site data removes these records from this browser and cannot be undone through the app. It does not delete anything you have separately copied or sent elsewhere.</p><h2>Hosting and security limits</h2><p>The website host may process access and security information under its own policies. This prototype has not been security-audited. Before public account registration, operator contact details, actual service providers, retention rules, and a route for privacy requests must be finalized.</p><p><button class="qa-link" data-nav="feedback">Prepare a privacy question or feedback →</button></p></article>`}
function feedbackView(){app.innerHTML=`<button class="back" data-nav="${state.hubOnboardingCompleted?'profile':'welcome'}">← Back</button><h1 class="page-title">Help make this useful.</h1><p class="subtitle">Tell JV what worked, what was confusing, or what you would improve.</p><form class="card" id="profileFeedbackForm"><label class="field">What is this about?<select name="topic"><option>Welcome & profile setup</option><option>Questions & answers</option><option>Library & search</option><option>Dashboard & badges</option><option>Appearance & navigation</option><option>Privacy question</option><option>Something else</option></select></label><label class="field">Your feedback<textarea name="message" required maxlength="3000" placeholder="What happened? What would make it better?"></textarea></label><label class="field">Device / browser (optional)<input name="device" maxlength="150" placeholder="e.g. iPhone / Safari"></label><p class="hint">Saved only in this browser. No email or profile details are included automatically.</p><button class="btn">Prepare feedback</button></form><div id="profileFeedbackOutput"></div>`;document.querySelector('#profileFeedbackForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.message.trim())return;const report={...d,createdAt:new Date().toISOString()};state.feedback.push(report);if(!persist()){state.feedback.pop();return}const text=`Toolbox — feedback\nTopic: ${d.topic}\nFeedback: ${d.message}\nDevice: ${d.device||'Not provided'}\nDate: ${report.createdAt}`;document.querySelector('#profileFeedbackOutput').innerHTML=`<div class="card"><h3 style="font-size:16px">Copy and send this to JV</h3><textarea class="feedback-prepared" id="profileFeedbackText" readonly aria-label="Prepared feedback">${esc(text)}</textarea><p><button class="btn quiet" id="copyProfileFeedback">Copy feedback</button></p><p class="hint">Nothing has been sent. Paste it into your existing conversation with JV.</p></div>`;document.querySelector('#copyProfileFeedback').onclick=async()=>{try{await navigator.clipboard.writeText(text);toast('Feedback copied. Paste it into your conversation with JV.')}catch{const area=document.querySelector('#profileFeedbackText');area.focus();area.select();toast('Select and copy the prepared feedback.')}}}}
function communityView(){const valid=/^https:\/\/(www\.)?facebook\.com\/groups\//.test(FACEBOOK_COMMUNITY_URL);app.innerHTML=`<button class="back" data-nav="profile">← Profile</button><section class="card community-panel"><div class="community-icon">f</div><h1 class="page-title">Join the crew on Facebook.</h1><p>A place to share app feedback, hear updates, and help shape the Toolbox. Your personal notes stay in Toolbox’s Library.</p>${valid?`<a class="btn" href="${esc(FACEBOOK_COMMUNITY_URL)}" target="_blank" rel="noopener noreferrer">Open Facebook community ↗</a><p class="hint">Opens Facebook separately. Facebook’s policies apply.</p>`:'<div class="qa-banner">The Facebook group link has not been added yet. JV will connect the official group before launch.</div><button class="btn quiet" data-nav="feedback">Prepare app feedback instead</button>'}</section>`}
nav=function(p){if(['welcome','gettingstarted','setup','privacy','feedback','community'].includes(p)){page=p;selected=null;render();window.scrollTo(0,0);return}if(!state.hubOnboardingCompleted){page='welcome';render();window.scrollTo(0,0);return}mainNavBeforeFlow(p)};
render=function(){if(!state.hubOnboardingCompleted&&!['welcome','gettingstarted','setup','privacy','feedback'].includes(page))page='welcome';const onboarding=!state.hubOnboardingCompleted;document.body.classList.toggle('intro-mode',onboarding);app.classList.remove('setup-view');applyTheme();if(page==='welcome'||page==='gettingstarted'||page==='setup'||page==='privacy'||page==='feedback'||page==='community'){renderNav();document.querySelector('#sectionName').textContent=({welcome:'A welcome from JV',gettingstarted:'Getting started',setup:'Set up your profile',privacy:'Privacy policy',feedback:'Feedback',community:'Facebook community'})[page];if(page==='welcome')welcomeView();if(page==='gettingstarted')gettingStartedView();if(page==='setup')profile(true);if(page==='privacy')privacyView();if(page==='feedback')feedbackView();if(page==='community')communityView();return}mainRenderBeforeFlow()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.themeChoice){const old=state.theme;state.theme=b.dataset.themeChoice;if(!persist())state.theme=old;applyTheme();render()}});
applyTheme();render();
